import java.util.HashMap;
import java.util.Map;

class Solution {
    public int numTriplets(int[] nums1, int[] nums2) {
        return countTriplets(nums1, nums2) + countTriplets(nums2, nums1);
    }

    private int countTriplets(int[] numsA, int[] numsB) {
        int count = 0;
        Map<Long, Integer> productCount = new HashMap<>();
        int n = numsB.length;

        // Count all products numsB[j] * numsB[k] for j < k
        for (int j = 0; j < n; j++) {
            for (int k = j + 1; k < n; k++) {
                long product = (long) numsB[j] * numsB[k];
                productCount.put(product, productCount.getOrDefault(product, 0) + 1);
            }
        }

        // For each element in numsA, check if its square is in productCount
        for (int x : numsA) {
            long square = (long) x * x;
            count += productCount.getOrDefault(square, 0);
        }

        return count;
    }
}

